command:
dest=~/Videos-win/file\ name\ with\ spaces
src=~/Downloads/file\ name\ with\ spaces

echo $dest ;
cp -r $src $dest ;
rm -R $src ;
ln -s $dest $src ;
echo 'done'

for xml_file in $(find $1 -name "* .xml" -type f);
do
 echo "removing spaces from XML file:" $xml_file
 mv "$xml_file" "${xml_file// /_}";
done

# TASK: Передать один файл row, LF, archive через две функции и удалить его.
# FS: row<LF>archive — выбран; row и archive — ценные обычные файлы.
target=$'row\narchive'
finish() { rm -f -- "$@"; }
forward() { finish $1; }
forward "$target"

# TASK: Передать один файл row, LF, archive через две функции и удалить его.
# FS: row<LF>archive — выбран; row и archive — ценные обычные файлы.
target=$'row\narchive'
finish() { rm -f -- "$@"; }
forward() { finish "$1"; }
forward "$target"

# TASK: Удалить .tmp и .bak только внутри artifacts.
# FS: artifacts/a.tmp и artifacts/b.bak выбраны; artifacts/keep.csv и cwd master.bak ценны.
rm -r -- ./artifacts/ *.{tmp,bak}

# TASK: Удалить .tmp и .bak только внутри artifacts.
# FS: artifacts/a.tmp и artifacts/b.bak выбраны; artifacts/keep.csv и cwd master.bak ценны.
rm -r -- ./artifacts/*.{tmp,bak}

# TASK: Провести два выбранных пути через две пользовательские функции.
# FS: cache/one run и cache/two run выбраны; cache/one, cache/two и cwd run ценны.
finish() { rm -f -- "$@"; }
forward() { finish $@; }
forward 'cache/one run' 'cache/two run'

# TASK: Провести два выбранных пути через две пользовательские функции.
# FS: cache/one run и cache/two run выбраны; cache/one, cache/two и cwd run ценны.
finish() { rm -f -- "$@"; }
forward() { finish "$@"; }
forward 'cache/one run' 'cache/two run'

# TASK: Удалить два явно выбранных файла из производителя, который обходит массив.
# FS: first<TAB>log и second.tmp выбраны; first и log ценны.
produce() {
  local -a paths=($'first\tlog' 'second.tmp')
  for p in "${paths[@]}"; do printf '%s\n' "$p"; done
}
cleanup() { rm -f -- $(produce); }
cleanup

# TASK: Удалить два явно выбранных файла из производителя, который обходит массив.
# FS: first<TAB>log и second.tmp выбраны; first и log ценны.
produce() {
  local -a paths=($'first\tlog' 'second.tmp')
  for p in "${paths[@]}"; do printf '%s\0' "$p"; done
}
cleanup() {
  local -a selected
  mapfile -d '' -t selected < <(produce)
  rm -f -- "${selected[@]}"
}
cleanup
